# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="25" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">EBOB VE EKOK ARASINDAKİ TEMEL MATEMATİKSEL ÖZELLİKLER (10.3.2)</text>\n  <rect x="20" y="42" width="320" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">GENEL ÖNERMELER VE EŞİTSİZLİKLER</text>\n  <text x="32" y="88" font-size="10.8" fill="#1e3a8a">• İki pozitif tam sayının çarpımı:</text>\n  <text x="42" y="106" font-size="11.2" font-weight="bold" fill="#1d4ed8">a · b = EBOB(a, b) · EKOK(a, b)</text>\n  <text x="32" y="128" font-size="10.8" fill="#1e3a8a">• a &lt; b ise sıralama bağıntısı:</text>\n  <text x="42" y="146" font-size="11" font-weight="bold" fill="#1d4ed8">1 ≤ EBOB(a, b) ≤ a &lt; b ≤ EKOK(a, b) ≤ a · b</text>\n  <text x="32" y="168" font-size="10.8" fill="#1e3a8a">• a sayısı b\'nin tam böleni ise (b = k · a):</text>\n  <text x="42" y="186" font-size="11" font-weight="bold" fill="#1d4ed8">EBOB(a, b) = a   ve   EKOK(a, b) = b</text>\n  <rect x="360" y="42" width="320" height="175" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="520" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">ARALARINDA ASAL SAYILAR (EBOB = 1)</text>\n  <text x="372" y="88" font-size="10.8" fill="#14532d">• 1\'den başka pozitif ortak böleni olmayan sayılara</text>\n  <text x="372" y="106" font-size="10.8" font-weight="bold" fill="#15803d">  aralarında asal sayılar denir.</text>\n  <text x="372" y="128" font-size="11.2" font-weight="bold" fill="#15803d">• EBOB(a, b) = 1   ve   EKOK(a, b) = a · b</text>\n  <text x="372" y="150" font-size="10.6" fill="#14532d">• Ardışık iki doğal sayı daima aralarında asaldır.</text>\n  <text x="372" y="170" font-size="10.6" fill="#14532d">• Ardışık iki tek sayı daima aralarında asaldır.</text>\n  <text x="372" y="190" font-size="10.6" fill="#14532d">• EBOB(a, b) = d ise a = d·x, b = d·y ve EBOB(x,y) = 1.</text>\n  <rect x="20" y="224" width="660" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.3" font-weight="bold" fill="#1e293b">Dikkat: a · b = EBOB · EKOK eşitliği iki sayı için her zaman geçerlidir; üç veya daha fazla sayı için genellenemez!</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="25" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">GERÇEK YAŞAM PROBLEMLERİNDE EBOB VE EKOK SEÇİM REHBERİ</text>\n  <rect x="20" y="42" width="320" height="175" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="180" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">BÜYÜKTEN KÜÇÜĞE → EBOB (BÖLME)</text>\n  <text x="32" y="88" font-size="10.6" fill="#78350f">• Çuvallardaki, bidonlardaki ürünleri hiç artmayacak</text>\n  <text x="32" y="106" font-size="10.6" fill="#78350f">  şekilde eşit büyüklükte poşet/şişelere paylaştırma</text>\n  <text x="32" y="126" font-size="10.6" fill="#78350f">• Farklı boydaki çubukları eşit uzunlukta parçalama</text>\n  <text x="32" y="146" font-size="10.6" fill="#78350f">• Tarla veya bahçe etrafına köşelere de gelmek</text>\n  <text x="32" y="164" font-size="10.6" fill="#78350f">  şartıyla eşit aralıklarla ağaç / direk dikme</text>\n  <text x="32" y="186" font-size="10.6" font-weight="bold" fill="#92400e">• Dikdörtgeni eş karelere, prizmayı eş küplere bölme</text>\n  <rect x="360" y="42" width="320" height="175" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="520" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">KÜÇÜKTEN BÜYÜĞE → EKOK (BİRLEŞTİRME)</text>\n  <text x="372" y="88" font-size="10.6" fill="#581c87">• Farklı periyotlarla çalan zillerin, kalkan otobüslerin,</text>\n  <text x="372" y="106" font-size="10.6" fill="#581c87">  nöbet tutanların tekrar aynı anda karşılaşması</text>\n  <text x="372" y="126" font-size="10.6" fill="#581c87">• Küçük dikdörtgen fayansları yan yana dizerek en</text>\n  <text x="372" y="144" font-size="10.6" fill="#581c87">  küçük alanı kaplayan kare zemin oluşturma</text>\n  <text x="372" y="164" font-size="10.6" fill="#581c87">• Küçük dikdörtgenler prizması tuğlalardan küp yapma</text>\n  <text x="372" y="186" font-size="10.6" font-weight="bold" fill="#6b21a8">• Cevizleri/çiçekleri üçer, dörder, beşer sayıp kalan bulma</text>\n  <rect x="20" y="224" width="660" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.3" font-weight="bold" fill="#1e293b">Kapalı şekil (tarla/üçgen/dikdörtgen) çevresinde ağaç sayısı = Çevre / EBOB; düz yolda ise (Uzunluk / EBOB) + 1\'dir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="25" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">PERİYODİK TEKRAR EDEN DURUMLAR VE KALANLI EKOK MODELLEMESİ</text>\n  <rect x="20" y="42" width="320" height="175" rx="10" fill="#ecfdf5" stroke="#059669" stroke-width="2"/>\n  <text x="180" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#065f46">KALANLI BÖLME VE EKOK GENELLEMESİ</text>\n  <text x="32" y="88" font-size="10.8" font-weight="bold" fill="#064e3b">Durum 1 (Sabit Kalan r):</text>\n  <text x="32" y="106" font-size="10.6" fill="#064e3b">A = a·x + r = b·y + r = c·z + r  (r &lt; a, b, c) ise;</text>\n  <text x="32" y="124" font-size="10.8" font-weight="bold" fill="#047857">→ A - r = EKOK(a, b, c) · k  ⇒  A = EKOK(a,b,c)·k + r</text>\n  <text x="32" y="148" font-size="10.8" font-weight="bold" fill="#064e3b">Durum 2 (Bölen - Kalan Farkı Sabit d):</text>\n  <text x="32" y="166" font-size="10.6" fill="#064e3b">A = a·x + (a - d) = b·y + (b - d) ise her tarafa d eklenir:</text>\n  <text x="32" y="186" font-size="10.8" font-weight="bold" fill="#047857">→ A + d = EKOK(a, b) · k  ⇒  A = EKOK(a, b)·k - d</text>\n  <rect x="360" y="42" width="320" height="175" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="520" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#9a3412">PERİYODİK PROBLEMLER (GÜN / SAAT)</text>\n  <text x="372" y="88" font-size="10.6" fill="#7c2d12">• Bir olay T günde bir tekrarlanıyorsa periyodu T\'dir.</text>\n  <text x="372" y="108" font-size="10.6" fill="#7c2d12">• 1. nöbet / karşılaşma başlangıç anıdır (0. periyot)!</text>\n  <text x="372" y="128" font-size="10.6" font-weight="bold" fill="#9a3412">• n. karşılaşma için geçen süre = (n - 1) · EKOK</text>\n  <text x="372" y="150" font-size="10.6" fill="#7c2d12">• Haftanın günleri 7 günde bir tekrar eder:</text>\n  <text x="380" y="168" font-size="10.5" fill="#7c2d12">Toplam gün sayısı 7\'ye bölünür; kalan kadar gün</text>\n  <text x="380" y="186" font-size="10.5" fill="#7c2d12">ileri (veya geçmiş soruluyorsa geri) sayılır.</text>\n  <rect x="20" y="224" width="660" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.3" font-weight="bold" fill="#1e293b">Kesim vs. Parça Sayısı: Bir çubuğu k eş parçaya ayırmak için (k - 1) kesim işlemi yapılır!</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
